def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = next(v for v, _ in counts.most_common() if v != background)

    # Locate the three-cell source pattern, oriented horizontally or vertically.
    source = None
    for dr, dc in ((0, 1), (1, 0)):
        for r in range(h):
            for c in range(w):
                cells = [(r + i * dr, c + i * dc) for i in range(3)]
                if all(0 <= rr < h and 0 <= cc < w for rr, cc in cells):
                    vals = [grid[rr][cc] for rr, cc in cells]
                    if all(v != background and v != marker for v in vals):
                        source = (dr, dc, vals, set(cells))
                        break
            if source:
                break
        if source:
            break

    if source is None:
        return [row[:] for row in grid]

    dr, dc, pattern, source_cells = source
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker and (r, c) not in source_cells]

    for r, c in markers:
        for i, value in enumerate(pattern):
            rr, cc = r + (i - 1) * dr, c + (i - 1) * dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out
